css:
/* ===== Twitter/X 发帖排版 · 黑底白字 · 直角卡片 ===== */
.be-card.be-custom {
  display: grid !important;
  grid-template-columns: 62px 1fr !important;
  gap: 0 8px !important;
  align-items: start !important;
  background: #000 !important;
  background-color: #000 !important;
  color: #fff !important;
  --be-card-bg: #000 !important;
  --be-card-fg: #fff !important;
  --be-card-sub: #71767b !important;
  padding: 0 !important;
  border-radius: 0 !important;
  overflow: visible !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
  box-shadow: none !important;
  min-height: 0 !important;
  position: relative !important;
  box-sizing: border-box !important;
  text-align: left !important;
  width: 100% !important;
}
.be-card.be-custom::before {
  content: 'ualwayss4ycute' !important;
  background-image: url('data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20width=%2222%22%20height=%2222%22%20viewBox=%220%200%2024%2024%22%20fill=%22none%22%20stroke=%22%23fff%22%20stroke-width=%222%22%20stroke-linecap=%22round%22%20stroke-linejoin=%22round%22%3E%3Cpath%20d=%22M19%2012H5%22/%3E%3Cpath%20d=%22M12%2019l-7-7%207-7%22/%3E%3C/svg%3E') !important;
  background-repeat: no-repeat !important;
  background-position: 14px center !important;
  grid-row: 1 !important;
  grid-column: 1 / -1 !important;
  width: 100% !important;
  height: 44px !important;
  display: block !important;
  text-align: center !important;
  line-height: 44px !important;
  font-size: 18px !important;
  font-weight: 700 !important;
  color: #fff !important;
  background-color: transparent !important;
  box-sizing: border-box !important;
}
.be-card.be-custom::after {
  content: url('data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20width=%2216%22%20height=%2216%22%20viewBox=%220%200%2024%2024%22%20fill=%22%2371767b%22%3E%3Ccircle%20cx=%2212%22%20cy=%225%22%20r=%222%22/%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%222%22/%3E%3Ccircle%20cx=%2212%22%20cy=%2219%22%20r=%222%22/%3E%3C/svg%3E') !important;
  position: absolute !important;
  top: 14px !important;
  right: 16px !important;
  width: 16px !important;
  height: 16px !important;
  z-index: 3 !important;
}
.be-card.be-custom .be-head,
.be-card.be-custom .be-meta,
.be-card.be-custom .be-source {
  display: contents !important;
}
.be-card.be-custom .be-char-avatar{display:block!important;
  grid-row: 2 / 4 !important;
  grid-column: 1 !important;
  width: 46px !important;
  height: 46px !important;
  min-width: 46px !important;
  border-radius: 50% !important;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  margin-left: 16px !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  flex-shrink: 0 !important;
}
.be-card.be-custom .be-avatar { display: none !important; }
.be-card.be-custom .be-source .author {
  grid-row: 2 !important;
  grid-column: 2 !important;
  display: block !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  background-color: transparent !important;
  color: #fff !important;
  font-size: 15px !important;
  font-weight: 700 !important;
  letter-spacing: normal !important;
  line-height: 1.2 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  position: relative !important;
  text-align: left !important;
}
.be-card.be-custom .be-source .author::before { content: '' !important; }
.be-card.be-custom .be-source .author::after { display: none !important; }
.be-card.be-custom .be-source .be-mask-block { background: transparent !important; background-color: transparent !important; color: #fff !important; }
.be-card.be-custom .be-source::after {
  content: '关注' !important;
  position: absolute !important;
  top: 52px !important;
  right: 16px !important;
  height: 28px !important;
  padding: 0 16px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: #000 !important;
  color: #fff !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  border: 2px solid #fff !important;
  border-radius: 14px !important;
  z-index: 4 !important;
  line-height: 1 !important;
  box-sizing: border-box !important;
}
.be-card.be-custom .be-name {
  grid-row: 3 !important;
  grid-column: 2 !important;
  display: block !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  background-color: transparent !important;
  color: #72a1d1 !important;
  font-size: 11.5px !important;
  font-weight: 400 !important;
  letter-spacing: normal !important;
  line-height: 1 !important;
  text-align: left !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: unset !important;
  position: relative !important;
  transform: translateY(-3px) !important;
}

.be-card.be-custom .be-name .be-mask-block { display: none !important; }
.be-card.be-custom .be-source .title,
.be-card.be-custom .be-source .chapter { display: none !important; }
.be-card.be-custom .be-date { display: none !important; }
.be-card.be-custom .be-quote {
  grid-row: 4 !important;
  grid-column: 1 / -1 !important;
  min-width: 0 !important;
  text-align: left !important;
  font-size: var(--be-quote-size, 16px) !important;
  line-height: var(--be-quote-lh, 1.45) !important;
  color: #fff !important;
  margin: 12px 16px 0 16px !important;
  padding: 0 !important;
  white-space: pre-wrap !important;
  overflow-wrap: break-word !important;
  word-break: break-word !important;
  box-sizing: border-box !important;
}
.be-card.be-custom .be-quote p {
  text-indent: 0 !important;
  margin: 0 0 0.5em 0 !important;
  color: #fff !important;
  white-space: pre-wrap !important;
  overflow-wrap: break-word !important;
}
.be-card.be-custom .be-date-cn {
  grid-row: 5 !important;
  grid-column: 1 / -1 !important;
  display: block !important;
  min-width: 0 !important;
  font-size: 13px !important;
  color: #71767b !important;
  margin: 8px 16px 0 16px !important;
  padding: 0 0 8px 0 !important;
  letter-spacing: normal !important;
  border-bottom: 1px solid #2f3336 !important;
  position: relative !important;
  text-align: left !important;
  opacity: 1 !important;
  background: transparent !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
.be-card.be-custom .be-date-cn::after {
  content: ' · 128万次查看' !important;
}
.be-card.be-custom .be-thought-main,
.be-card.be-custom .be-quote-orig { display: none !important; }
.be-card.be-custom .be-watermark {
  grid-row: 6 !important;
  grid-column: 1 / -1 !important;
  min-width: 0 !important;
  font-size: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  color: transparent !important;
  background: #000 !important;
  background-color: #000 !important;
  width: 100% !important;
  line-height: 0 !important;
  overflow: hidden !important;
  display: block !important;
}
.be-card.be-custom .be-watermark::before {
  content: url('data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20width=%22300%22%20height=%2220%22%20viewBox=%220%200%20300%2020%22%20preserveAspectRatio=%22none%22%3E%3Cstyle%3Etext%7Bfont-family:-apple-system,BlinkMacSystemFont,%22Segoe%20UI%22,Roboto,%22Helvetica%20Neue%22,Arial,sans-serif;font-size:14px;%7D.num%7Bfill:%23fff;font-weight:700;%7D.lbl%7Bfill:%2372a1d1;font-weight:400;%7D%3C/style%3E%3Ctext%20x=%2216%22%20y=%2215%22%3E%3Ctspan%20class=%22num%22%3E0%3C/tspan%3E%3Ctspan%20class=%22lbl%22%20dx=%223%22%3E%E8%BD%AC%E6%8E%A8%3C/tspan%3E%3C/text%3E%3Ctext%20x=%2285%22%20y=%2215%22%3E%3Ctspan%20class=%22num%22%3E0%3C/tspan%3E%3Ctspan%20class=%22lbl%22%20dx=%223%22%3E%E5%BC%95%E7%94%A8%E6%8E%A8%E6%96%87%3C/tspan%3E%3C/text%3E%3Ctext%20x=%22180%22%20y=%2215%22%3E%3Ctspan%20class=%22num%22%3E0%3C/tspan%3E%3Ctspan%20class=%22lbl%22%20dx=%223%22%3E%E5%96%9C%E6%AC%A2%3C/tspan%3E%3C/text%3E%3C/svg%3E') !important;
  display: block !important;
  width: 100% !important;
  height: 20px !important;
  border-bottom: 1px solid #2f3336 !important;
  margin-top: 4px !important;
  padding: 0 !important;
}
.be-card.be-custom .be-watermark::after { display: none !important; }

comments:
/* ===== X / 推特 · 评述模块（黑底白字，分割线分隔） ===== */
.be-comments {
  background: #000;
  border-top: 1px solid #2f3336;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}
.be-comment {
  display: flex;
  gap: 10px;
  padding: 11px 16px;
  border-bottom: 1px solid #2f3336;
}
.be-comment:last-child { border-bottom: none; }
.be-comment-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  background-color: #2f3336;
  flex-shrink: 0;
}
.be-comment-main { flex: 1; min-width: 0; }
.be-comment-meta { display: flex; align-items: baseline; flex-wrap: wrap; gap: 3px 6px; }
.be-comment-name { font-size: 14px; font-weight: 700; color: #fff; }
.be-comment-id { font-size: 13px; color: #71767b; }
.be-comment-time { font-size: 13px; color: #71767b; }
.be-comment-text { font-size: 14px; color: #e7e9ea; line-height: 1.5; margin-top: 3px; white-space: pre-wrap; overflow-wrap: break-word; }
.be-comment[data-kind="user"] .be-comment-name { color: #72a1d1; }
